/**
 * Print the actual Lighthouse reports generated by LHCI, not merely CI pass/fail.
 * A successful CI job may still have warn-level Lighthouse assertions.
 */
import { readdir, readFile, appendFile } from 'node:fs/promises';
import { join } from 'node:path';

const dir = join(process.cwd(), 'lighthouse-reports');
let filenames = [];
try { filenames = (await readdir(dir)).filter(name => name.endsWith('.json') && name !== 'manifest.json'); }
catch (_) { console.log('No Lighthouse report directory available (LHCI may have failed).'); process.exit(0); }

const reports = [];
for (const name of filenames) {
  try {
    const data = JSON.parse(await readFile(join(dir, name), 'utf8'));
    if (data.categories?.performance && data.finalUrl) reports.push(data);
  } catch (_) { /* Skip malformed or auxiliary files; never fabricate scores. */ }
}
if (!reports.length) {
  console.log('Lighthouse reports absent; no performance score can be claimed.');
  process.exit(0);
}
const score = (value) => typeof value === 'number' ? String(Math.round(value * 100)) : 'n/a';
const audit = (lhr, id) => lhr.audits?.[id]?.displayValue ?? 'n/a';
const lines = [
  '### PostChars Lighthouse lab results (real report values)',
  '',
  '| URL | Performance | Accessibility | SEO | LCP | CLS | TBT |',
  '| --- | ---: | ---: | ---: | --- | --- | --- |'
];
for (const r of reports) {
  const name = new URL(r.finalUrl).pathname;
  lines.push('| ' + name + ' | ' + score(r.categories.performance?.score) +
    ' | ' + score(r.categories.accessibility?.score) +
    ' | ' + score(r.categories.seo?.score) +
    ' | ' + audit(r, 'largest-contentful-paint') +
    ' | ' + audit(r, 'cumulative-layout-shift') +
    ' | ' + audit(r, 'total-blocking-time') + ' |');
}
lines.push('', 'Lab scores are single-run snapshots, not CrUX/Core Web Vitals field measurements. Existing LHCI thresholds are warnings and do not guarantee passing scores.');
const output = lines.join('\n') + '\n';
console.log(output);
if (process.env.GITHUB_STEP_SUMMARY) await appendFile(process.env.GITHUB_STEP_SUMMARY, output, 'utf8');
